import{_ as t,a,c as i,ac as o}from"./chunks/framework.BSuaGltH.js";const h=JSON.parse('{"title":"Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","frontmatter":{"title":"Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态","description":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","splitFrom":"systems/linux/common-commands.md","showdocs":{"topics":[{"id":"linux","title":"Linux","link":"/topics/linux/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"命令与系统观察","scope":"general","audience":"general","group":"容器与运维","seriesTitle":"Linux 常用命令：用途、参数与操作边界","summary":"把基础解释与按使用流程排列的命令表集中为一个速查入口。","status":"active","related":[{"title":"Linux 常用命令：用途、参数与操作边界","link":"/systems/linux/common-commands","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 按发行版选择包管理器至备份与同步","link":"/systems/linux/common-commands-part-06","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 浏览、创建与移动文件至文本筛选、统计与比较","link":"/systems/linux/common-commands-part-04","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 维护与旧设备场景","link":"/systems/linux/common-commands-part-07","kind":"命令与系统观察","scope":"general","audience":"general"},{"title":"Linux 常用命令：用途、参数与操作边界 · 账号、权限与属性至磁盘容量与挂载","link":"/systems/linux/common-commands-part-05","kind":"命令与系统观察","scope":"general","audience":"general"}],"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · Linux 基础命令","link":"/systems/linux/common-commands-part-01"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · ps 列出当前系统进程至Linux 常用命令","link":"/systems/linux/common-commands-part-03"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"Linux 常用命令：用途、参数与操作边界 · Linux 基础命令","link":"/systems/linux/common-commands-part-01"},"next":{"text":"Linux 常用命令：用途、参数与操作边界 · ps 列出当前系统进程至Linux 常用命令","link":"/systems/linux/common-commands-part-03"}},"headers":[],"relativePath":"systems/linux/common-commands-part-02.md","filePath":"systems/linux/common-commands-part-02.md"}'),s={name:"systems/linux/common-commands-part-02.md"};function n(c,e,p,l,d,u){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="linux-常用命令-用途、参数与操作边界-·-touch-创建新文件至top-实时显示进程状态" tabindex="-1">Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态 <a class="header-anchor" href="#linux-常用命令-用途、参数与操作边界-·-touch-创建新文件至top-实时显示进程状态" aria-label="Permalink to &quot;Linux 常用命令：用途、参数与操作边界 · touch 创建新文件至top 实时显示进程状态&quot;">​</a></h1><p><a href="/systems/linux/common-commands">返回分篇目录</a></p><p>先按任务进入主速查；需要理解参数时再展开后面的逐条解释。命令未执行，平台与权限按相应条目核对。</p><h2 id="part-1-touch-创建新文件" tabindex="-1">touch 创建新文件 <a class="header-anchor" href="#part-1-touch-创建新文件" aria-label="Permalink to &quot;touch 创建新文件 {#part-1-touch-创建新文件}&quot;">​</a></h2><p>&quot;touch&quot; 命令用于创建新文件或更新已有文件的修改时间。以下是 &quot;touch&quot; 命令的详解：</p><ul><li>格式：touch [选项] 文件</li><li>选项：touch 命令支持许多选项，其中一些最常用的选项包括： <ul><li>-a：只更改文件的访问时间。</li><li>-m：只更改文件的修改时间。</li><li>-c：不创建不存在的文件。</li><li>-t：指定要设置的时间戳，格式为 <code>[[CC]YY]MMDDhhmm[.SS]</code></li></ul></li><li>文件：要创建或更新时间戳的文件名称。</li></ul><p>举个例子，如果要在当前工作目录下创建一个名为 &quot;test.txt&quot; 的空文件，可以输入 &quot;touch test.txt&quot; 命令。如果要更新已有文件的修改时间，可以使用 &quot;touch filename&quot; 命令。如果需要只更改文件的访问时间或修改时间，可以使用 &quot;-a&quot; 或 &quot;-m&quot; 选项，例如 &quot;touch -a filename&quot; 命令只更改文件的访问时间。如果希望不创建不存在的文件，则可以使用 &quot;-c&quot; 选项，例如 &quot;touch -c filename&quot; 命令。如果需要指定要设置的时间戳，则可以使用 &quot;-t&quot; 选项，例如 &quot;touch -t 202201011200.00 filename&quot; 命令将文件的时间戳设置为 2022 年 1 月 1 日 12:00。</p><p>需要注意的是，在使用 &quot;touch&quot; 命令时，如果指定的文件不存在，则会创建一个空文件。在更新时间戳时，需要确保具有足够的权限，并且谨慎操作以避免误操作。</p><h2 id="part-1-cat-连接、显示文件内容" tabindex="-1">cat 连接、显示文件内容 <a class="header-anchor" href="#part-1-cat-连接、显示文件内容" aria-label="Permalink to &quot;cat 连接、显示文件内容 {#part-1-cat-连接、显示文件内容}&quot;">​</a></h2><p>&quot;cat&quot; 命令用于显示文件内容或将多个文件合并成一个文件。以下是 &quot;cat&quot; 命令的详解：</p><ul><li>格式：cat [选项] 文件</li><li>选项：cat 命令支持许多选项，其中一些最常用的选项包括： <ul><li>-n：在输出文件的每一行前插入行号。</li><li>-b：在输出文件的非空行前插入行号。</li><li>-s：压缩连续空白行为一行。</li><li>-A：显示特殊字符（如文本中的制表符和换行符）。</li></ul></li><li>文件：要显示内容或合并的文件名称。</li></ul><p>举个例子，如果要查看当前工作目录下名为 &quot;test.txt&quot; 的文件内容，可以输入 &quot;cat test.txt&quot; 命令。如果要合并两个文件 &quot;file1&quot; 和 &quot;file2&quot; 并将结果写入新文件 &quot;output&quot; 中，可以使用 &quot;cat file1 file2 &gt; output&quot; 命令。如果需要在输出文件的每一行前插入行号，则可以使用 &quot;-n&quot; 选项，例如 &quot;cat -n filename&quot; 命令会输出带行号的文件内容。如果需要将连续空白行压缩成一行，则可以使用 &quot;-s&quot; 选项，例如 &quot;cat -s filename&quot; 命令会输出压缩后的文件内容。</p><p>需要注意的是，在显示文件之前，需要确保已经具有足够的权限来访问文件。在合并文件时，需要确保所有要合并的文件存在，并且目标文件没有被保护或已经存在，以避免数据丢失。</p><h2 id="part-1-grep-文本搜索工具" tabindex="-1">grep 文本搜索工具 <a class="header-anchor" href="#part-1-grep-文本搜索工具" aria-label="Permalink to &quot;grep 文本搜索工具 {#part-1-grep-文本搜索工具}&quot;">​</a></h2><p><code>grep</code> 命令是一种文本搜索工具，常用于从文件中查找某个特定的字符串或者正则表达式，并且可以显示匹配行的内容。</p><p>以下是 <code>grep</code> 命令的基本语法：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grep [options] pattern [file]</span></span></code></pre></div><p>其中，<code>pattern</code> 为要匹配的模式，可以是一个字符串或者一个正则表达式；<code>file</code> 则为要搜索的文件名。</p><p>下面是常用的一些选项：</p><ul><li><code>-i</code>: 忽略大小写。</li><li><code>-v</code>: 显示不匹配的行。</li><li><code>-n</code>: 显示匹配行的行号。</li><li><code>-l</code>: 只显示包含匹配项的文件名。</li><li><code>-c</code>: 统计匹配行的数量。</li><li><code>-r</code>: 在目录及其子目录下递归搜索。</li></ul><p>例如，以下命令将在文件 <code>example.txt</code> 中搜索所有包含字符串 &quot;hello&quot; 的行：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grep &quot;hello&quot; example.txt</span></span></code></pre></div><p>如果要忽略大小写，可以使用 <code>-i</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grep -i &quot;hello&quot; example.txt</span></span></code></pre></div><p>如果要显示匹配行的行号，可以使用 <code>-n</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grep -n &quot;hello&quot; example.txt</span></span></code></pre></div><p>如果要递归搜索目录 <code>mydir</code> 下的所有文件，可以使用 <code>-r</code> 选项：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>grep -r &quot;hello&quot; mydir/</span></span></code></pre></div><h2 id="part-1-ping-测试网络连接" tabindex="-1">ping 测试网络连接 <a class="header-anchor" href="#part-1-ping-测试网络连接" aria-label="Permalink to &quot;ping 测试网络连接 {#part-1-ping-测试网络连接}&quot;">​</a></h2><p><code>ping</code> 命令用于检查网络连接是否正常，可以测试与目标主机之间的连通性和网络延迟。它发送一个 ICMP ECHO 请求消息到指定的目的地，并等待接收一个 ICMP ECHO 响应消息。</p><p>以下是 <code>ping</code> 命令的基本语法：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ping [options] target</span></span></code></pre></div><p>其中，<code>target</code> 可以是 IP 地址或者域名，表示需要对这个地址进行 ping 测试。</p><p>下面是一些常用的选项：</p><ul><li><code>-c count</code>: 指定要发送的 ICMP 请求消息的次数。</li><li><code>-i interval</code>: 指定发送 ICMP 请求消息的时间间隔（以秒为单位）。</li><li><code>-s size</code>: 指定每个 ICMP 请求消息的数据包大小（默认为 56 字节）。</li><li><code>-t ttl</code>: 指定 ICMP 数据报中的 Time To Live 值（默认为 64）。</li><li><code>-w deadline</code>: 指定等待响应的最大时间（以秒为单位）。</li></ul><p>例如，以下命令将向 IP 地址为 <code>192.168.1.1</code> 发送 5 个 ICMP 请求消息：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ping -c 5 192.168.1.1</span></span></code></pre></div><p>在 Linux 中，不指定次数即可持续发送，按 Ctrl+C 停止；-t 用于设置 TTL：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ping google.com</span></span></code></pre></div><h2 id="part-1-ifconfig-查看和配置网络接口状态" tabindex="-1">ifconfig 查看和配置网络接口状态 <a class="header-anchor" href="#part-1-ifconfig-查看和配置网络接口状态" aria-label="Permalink to &quot;ifconfig 查看和配置网络接口状态 {#part-1-ifconfig-查看和配置网络接口状态}&quot;">​</a></h2><p><code>ifconfig</code>（interface configuration）命令是用于配置和显示网络接口信息的工具。它可以列出当前系统中所有的网络接口，包括以太网、无线网络、回环接口等，并且可以查看和修改这些接口的 IP 地址、子网掩码、MAC 地址等配置信息。</p><p>以下是 <code>ifconfig</code> 命令的基本语法：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ifconfig [options] [interface]</span></span></code></pre></div><p>其中，<code>interface</code> 表示要操作的网络接口的名称，如果省略则默认显示所有接口的信息。</p><p>下面是一些常用的选项：</p><ul><li><code>-a</code>: 显示所有接口的信息，包括未激活的接口。</li><li><code>up</code>: 启动指定的接口。</li><li><code>down</code>: 关闭指定的接口。</li><li><code>inet addr</code>: 指定 IPv4 地址。</li><li><code>netmask mask</code>: 指定子网掩码。</li><li><code>hw ether MAC</code>: 指定 MAC 地址。</li></ul><p>例如，以下命令将显示所有网络接口的信息：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ifconfig -a</span></span></code></pre></div><p>如果想要启动一个被禁止的网络接口（如 eth0），可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ifconfig eth0 up</span></span></code></pre></div><p>如果想要修改一个接口的 IP 地址和子网掩码，可以使用以下命令：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ifconfig eth0 inet 192.168.1.10 netmask 255.255.255.0</span></span></code></pre></div><p>以上是 <code>ifconfig</code> 命令的一些基本用法和选项。需要注意的是，<code>ifconfig</code> 命令已经被新的 <code>ip</code> 命令取代，因此在一些新的 Linux 发行版中可能已经不再支持 <code>ifconfig</code> 命令。</p><h2 id="part-1-top-实时显示进程状态" tabindex="-1">top 实时显示进程状态 <a class="header-anchor" href="#part-1-top-实时显示进程状态" aria-label="Permalink to &quot;top 实时显示进程状态 {#part-1-top-实时显示进程状态}&quot;">​</a></h2><p><code>top</code> 命令用于实时监控系统的进程和资源使用情况，可以查看哪些进程占用了 CPU 时间、内存、虚拟内存等系统资源，并且可以按照不同的指标进行排序。</p><p>以下是 <code>top</code> 命令的基本语法：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>top</span></span></code></pre></div><p>运行该命令后，会显示当前系统中所有进程的信息，按照 CPU 占用率进行排序，上方的几行显示了系统的总体信息，包括系统负载、运行进程数、CPU 使用情况、内存使用情况等。下面的每一行显示了一个具体的进程的信息，包括进程 ID、占用 CPU 的百分比、内存占用量、进程所属用户等。</p><p>下面是一些常用的交互命令：</p><ul><li><code>q</code>: 退出 <code>top</code> 命令。</li><li><code>k</code>: 结束某个进程，需要输入要终止的进程 ID。</li><li><code>f</code>: 显示或隐藏需要显示的字段，可以选择要显示的列，如 PID、CPU、MEM 等。</li><li><code>r</code>: 修改某个进程的优先级，需要输入要修改的进程 ID 和新的优先级值。</li></ul><p>例如，以下命令将启动 <code>top</code> 命令并按照内存占用率进行排序：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>top -o %MEM</span></span></code></pre></div><p>如果想要显示更多的进程信息，可以使用 <code>f</code> 命令选择要显示的字段：</p><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>top -o %CPU</span></span></code></pre></div><p>以上是 <code>top</code> 命令的一些基本用法和选项。需要注意的是，<code>top</code> 命令只能在交互式命令行环境下使用，如果需要在脚本中监控系统进程和资源使用情况，可以考虑使用其他工具，如 <code>ps</code> 命令等。</p>',65)])])}const g=t(s,[["render",n]]);export{h as __pageData,g as default};
